img.banner {
  margin: 0 auto;
  /* النتيجة: الصورة ترفض التوسيط وتظل ملتصقة بالطرف! */
}

.badge {
  clip-path: polygon(0 0, 100% 0, 100% 100%);
  /* النتيجة: مثلث مقصوص لكن الأقواس تفتقر إلى نقطة الإغلاق الرابعة */
}

img.card-img {
  width: 100%;
  height: 250px;
  /* النتيجة: الصورة ممطوطة ومضغوطة بصورة قبيحة */
}

.profile-cover {
  object-fit: cover;
  object-position: center;
  /* المشكلة: وجوه الأشخاص في أعلى الصورة يتم قصها وتختفي */
}

.faded-img {
  mask-image: linear-gradient(black, transparent);
  /* المشكلة: لا يعمل في متصفحات WebKit القديمة كـ Safari و Chrome */
}
